import java.util.*;

import jakarta.persistence.*;
import org.hibernate.cfg.Configuration;

public class Main {
    public static void main(String[] args) {
        EntityManagerFactory emf = Jpa.buat(false, Langganan.class);
        EntityManager em = emf.createEntityManager();
        Scanner in = new Scanner(System.in);
        em.getTransaction().begin();
        while (in.hasNextLine()) {
            String[] d = in.nextLine().split(";");
            em.persist(new Langganan(d[0], Paket.valueOf(d[1])));
        }
        em.getTransaction().commit();
        for (Object[] b : (List<Object[]>) em.createNativeQuery("select nama, paket from Langganan order by id").getResultList()) {
            System.out.println(b[0] + " " + b[1]);
        }
        em.close();
        emf.close();
    }
}

